// 1시간에 한 번만 알린다(같은 장애로 6번 울리지 않게). 상태는 워크플로 static data 에 보관.
const s = $getWorkflowStaticData('global');
const body = $input.first().json;
const now = Date.now();
const suspected = body.fallback_suspected === true;
const lastAlert = s.lastAlertAt || 0;
const recovered = !suspected && s.alerting === true;
let fire = null;
if (suspected && now - lastAlert > 60 * 60 * 1000) {
  s.lastAlertAt = now; s.alerting = true;
  fire = `:rotating_light: *Gemini 한도 초과 의심* — 최근 1시간 429 ${body.quota_429_last_hour}회 (24시간 ${body.quota_429_last_24h}회, 마지막 ${body.last_429_at ?? '-'}).\nAI 기능(온보딩·요약·코스 선택기)이 폴백으로 돌고 있습니다. 모델: ${body.model}. 결제 연결 안 됐으면 이슈 #99 참고.`;
}
if (recovered) {
  s.alerting = false;
  fire = `:white_check_mark: Gemini 429 가 1시간 동안 없습니다 — 정상 복귀 (마지막 성공 ${body.last_success_at ?? '-'}).`;
}
return fire ? [{ json: { text: fire } }] : [];
